/* ---------- ESPÉCIES & PLANTIOS ---------- */
prod:{title:'Espécies & Plantios',crumb:'Ações',
  desc:'Inventário botânico dos plantios do Flore-Ser: espécies plantadas e previstas nos espaços públicos, com categoria (nativa, PANC, frutífera, medicinal), origem da muda e situação no viveiro. Filtre por situação ou destaque as nativas do Cerrado.',
  render:()=>{
   const nat=PRODUCOES.filter(p=>p.intl).length;
   const pancMed=PRODUCOES.filter(p=>/panc|medicinal/i.test(p.cat||p.j||'')).length;
   const cats=new Set(PRODUCOES.map(p=>p.tipo)).size;
   const porTipo={}; PRODUCOES.forEach(p=>{const t=p.tipo||'Outras'; porTipo[t]=(porTipo[t]||0)+1;});
   const lev=CITIES.find(c=>c.levantamento);
   const levTot=lev?lev.levantamento.arvores+lev.levantamento.cactos+lev.levantamento.ornamentais:0;
   const cores=['#5c6a34','#38512f','#c0603a','#e5286e','#d89b34','#b0472a','#8a9a52'];
   const slices=Object.keys(porTipo).map((t,i)=>({label:t,value:porTipo[t],color:cores[i%cores.length]}));
   return `
   ${elKPIs([
     {lbl:'Espécies catalogadas',val:String(PRODUCOES.length),accent:'cyan',foot:'catálogo de referência do projeto'},
     {lbl:'Nativas do Cerrado',val:String(nat),accent:'green',foot:'prioridade de plantio'},
     {lbl:'PANCs e medicinais',val:String(pancMed),accent:'blue',foot:'alimentação e uso popular'},
     {lbl:'Categorias botânicas',val:String(cats),accent:'amber',foot:'árvores, herbáceas, arbustos…'}
   ])}
   <div class="filters" id="prodFilters">
     <button class="pill on" data-st="all">Todas</button>
     <button class="pill" data-st="Validado">Plantadas</button>
     <button class="pill" data-st="Pendente">Previstas</button>
     <button class="pill" data-st="intl">Nativas do Cerrado</button>
   </div>
   <div class="grid grid-2">
     <div id="prodList" style="display:flex;flex-direction:column;gap:12px"></div>
     <div class="stack">
       ${lev?elBars({title:'Levantamento botânico · '+lev.city,sub:`plantas vivas desde ${lev.levantamento.desde} · registro de campo`,series:[
         {label:'Plantas ornamentais',value:lev.levantamento.ornamentais,color:'#5c6a34'},
         {label:'Árvores',value:lev.levantamento.arvores,color:'#38512f'},
         {label:'Cactos',value:lev.levantamento.cactos,color:'#c0603a'}],
         legend:`<div style="margin-top:10px;font-size:11.5px;color:var(--text-3)">${fmt(levTot)} plantas no primeiro levantamento por espaço do projeto.</div>`}):''}
       ${elDonut({title:'Por categoria de espécie',centerVal:String(PRODUCOES.length),centerLbl:'Espécies',slices})}
       ${elNote({title:'Sobre o inventário botânico',intro:'O Flore-Ser prioriza espécies nativas do Cerrado, além de PANCs, medicinais e frutíferas:',refs:[
         {k:'Nativas do Cerrado',v:'Ipê, aroeira, jatobá, baru e pequi sustentam a fauna urbana e resistem à seca.'},
         {k:'PANCs e medicinais',v:'Plantas alimentícias não convencionais e ervas de uso popular integram hortas e canteiros.'},
         {k:'Contagem por espaço',v:`Primeiro levantamento concluído: ${lev?lev.city:'Humanidades 2'}, com ${lev?fmt(levTot):'447'} plantas vivas desde ${lev?lev.levantamento.desde:2024}.`}
       ]})}
     </div>
   </div>`;
  }},

