/* ---------- ESPAÇOS PÚBLICOS ---------- */
espacos:{title:'Espaços Públicos',crumb:'Território',
  desc:'Catálogo dos espaços públicos atendidos pelo Flore-Ser em Goiânia: praças, canteiros, campi da UFG, CMEIs e escolas municipais e estaduais. Os espaços-piloto (Biblioteca Central e Humanidades 2) abriram o projeto e servem de referência metodológica para os demais.',
  render:()=>{
    const PIL=['Biblioteca Central','Humanidades 2'];
    const regs=[...new Set(CITIES.map(c=>c.cont))];
    const mx=Math.max(...CITIES.map(c=>c.out+c.in),1);
    const cards=CITIES.slice().sort((a,b)=>(b.out+b.in)-(a.out+a.in)).map(c=>{
      const pil=PIL.includes(c.city), tot=c.out+c.in, feito=c.status==='realizado';
      return `<div class="card tight esp-item" data-reg="${_escAttr(c.cont)}"${feito?'':' style="opacity:.72"'}>
        <div class="card-h">
          <h2>${_escHTML(c.city)}${pil?' <span class="chip am">piloto</span>':''}</h2>
          <span class="sub">${_escHTML(c.cont)}</span>
        </div>
        <div class="tagrow" style="margin:-6px 0 10px">${feito?'<span class="chip gr">Atividade realizada</span>':'<span class="chip">Ainda não iniciado</span>'}</div>
        <div class="mini-stat">
          <div><span class="n" style="color:var(--green)">${feito?c.out:'·'}</span><span class="l">ações</span></div>
          <div><span class="n" style="color:var(--blue)">${feito?c.in:'·'}</span><span class="l">participantes</span></div>
          <div><span class="n">${feito?tot:'·'}</span><span class="l">total</span></div>
        </div>
        ${feito?`<div class="gb-line" style="margin-top:10px"><div class="gb-track"><div class="gb-out" style="height:100%;width:${(tot/mx*100).toFixed(0)}%"></div></div></div>`:''}
      </div>`;
    }).join('');
    return `
   ${elKPIs([
     {lbl:'Espaços mapeados',val:String(CITIES.length),accent:'cyan',foot:'praças, canteiros, campi e escolas'},
     {lbl:'Com atividade realizada',val:String(CITIES.filter(c=>c.status==='realizado').length),accent:'green',foot:'já ativados pelo projeto'},
     {lbl:'Regiões de Goiânia',val:String(regs.length),accent:'amber',foot:'cobertura territorial'},
     {lbl:'Ações realizadas',val:fmt(CITIES.filter(c=>c.status==='realizado').reduce((s,c)=>s+c.out,0)),accent:'blue',foot:'no inventário do projeto'}
   ])}
   <div class="filters" id="espFiltros" style="margin-top:14px">
     <button class="pill on" data-reg="todos">Todas as regiões</button>
     ${regs.map(r=>`<button class="pill" data-reg="${_escAttr(r)}">${_escHTML(r)}</button>`).join('')}
   </div>
   <div class="grid grid-3" id="espGrid" style="margin-top:14px">${cards}</div>`;
  }},

