function perfTag(c,t){return `<span class="chip" style="background:${c}22;border-color:${c}55;color:${c}">${t}</span>`;}
function personStats(arr){return `<div class="mini-stat">`+arr.map(([l,n])=>`<div><span class="n">${n}</span><span class="l">${l}</span></div>`).join('')+`</div>`;}
