/* ===== globo 3D REALISTA (hero): Three.js: bordas de países, pontos de terra, arcos e tour cinematográfico
   Mesmo padrão do widget hero-globo (CapesHeroGlobo): globo transparente, contornos glow,
   pontos de terra, malha de arcos com partículas viajantes e auto-rotação cinematográfica. ===== */
const THREE_CDN='https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js';
const TOPOJSON_CDN='https://cdn.jsdelivr.net/npm/topojson-client@3.1.0/dist/topojson-client.min.js';
const WORLD_DATA_URL='data/world.json';
let HERO_GLOBE=null;            // instância 3D ativa { destroy() }
let __heroLibsPromise=null;

function loadScriptOnce(src){
  return new Promise((res,rej)=>{
    if([...document.scripts].some(s=>s.src===src)) return res();
    const s=document.createElement('script');
    s.src=src; s.onload=()=>res(); s.onerror=()=>rej(new Error('falha ao carregar '+src));
    document.head.appendChild(s);
  });
}
function ensureGlobeLibs(){
  if(window.THREE && window.topojson) return Promise.resolve();
  if(!__heroLibsPromise){
    __heroLibsPromise=(async()=>{
      if(!window.THREE) await loadScriptOnce(THREE_CDN);
      if(!window.topojson) await loadScriptOnce(TOPOJSON_CDN);
    })();
  }
  return __heroLibsPromise;
}

function initHeroGlobe(){
  const cv=document.getElementById('heroGlobe'); if(!cv) return;
  if(HERO_GLOBE){ try{HERO_GLOBE.destroy();}catch(_){} HERO_GLOBE=null; }
  ensureGlobeLibs().then(()=>{
    if(!document.body.contains(cv)) return;     // trocou de view enquanto carregava
    HERO_GLOBE=buildHeroGlobe(cv);
  }).catch(err=>console.error('[Hero Globo]',err&&err.message||err));
}

function buildHeroGlobe(canvas){
  const THREE=window.THREE;
  if(!THREE) return {destroy(){}};

  const renderer=new THREE.WebGLRenderer({canvas:canvas,alpha:true,antialias:true});
  renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));
  const scene=new THREE.Scene();
  const GLOBE_Z=2.6;   /* mais perto que o original (3.5): enquadra o Brasil/Cerrado */
  const camera=new THREE.PerspectiveCamera(35,1,0.1,100);
  camera.position.z=GLOBE_Z;
  const globe=new THREE.Group(); scene.add(globe);

  function ll3(lat,lng,r){
    r=r||1;
    const phi=(90-lat)*Math.PI/180, theta=(lng+180)*Math.PI/180;
    return new THREE.Vector3(
      -r*Math.sin(phi)*Math.cos(theta),
       r*Math.cos(phi),
       r*Math.sin(phi)*Math.sin(theta)
    );
  }

  // Centro: UFG · Goiânia
  const center=ll3(HUB.lat,HUB.lon,1.012);
  const centerDot=new THREE.Mesh(new THREE.SphereGeometry(0.024,16,16),new THREE.MeshBasicMaterial({color:0xffffff}));
  centerDot.position.copy(center); globe.add(centerDot);
  const centerGlow=new THREE.Mesh(new THREE.SphereGeometry(0.045,16,16),new THREE.MeshBasicMaterial({color:0x7dcfff,transparent:true,opacity:0.4}));
  centerGlow.position.copy(center); globe.add(centerGlow);
  const pulseRings=[];
  for(let i=0;i<3;i++){
    const ring=new THREE.Mesh(new THREE.RingGeometry(0.035,0.042,40),new THREE.MeshBasicMaterial({color:0x7dcfff,transparent:true,opacity:0.7,side:THREE.DoubleSide}));
    ring.position.copy(center); ring.lookAt(new THREE.Vector3(0,0,0)); ring.userData.offset=i/3;
    globe.add(ring); pulseRings.push(ring);
  }

  // ---- Mundo (world.json topojson) com fallback offline para LAND_POLY ----
  fetch(WORLD_DATA_URL)
    .then(r=>{ if(!r.ok) throw new Error('world.json indisponível'); return r.json(); })
    .then(topo=>{
      let features=null;
      if(topo.type==='Topology'&&topo.objects&&window.topojson){
        const keys=Object.keys(topo.objects);
        const key=keys.indexOf('countries')>=0?'countries':keys[0];
        features=window.topojson.feature(topo,topo.objects[key]).features;
      } else if(topo.type==='FeatureCollection'){ features=topo.features; }
      else throw new Error('formato desconhecido');
      renderCountryBorders(features); renderLandDots(features);
    })
    .catch(()=>renderFallbackLand());

  function renderCountryBorders(features){
    const worldPos=[], brPos=[];
    features.forEach(f=>{
      const g=f.geometry; if(!g) return;
      const props=f.properties||{};
      const name=props.name||props.NAME||props.ADMIN||'';
      const isBrazil=name==='Brazil'||name==='Brasil'||f.id==='BRA'||f.id==='076'||f.id===76;
      const target=isBrazil?brPos:worldPos, radius=isBrazil?1.010:1.008;
      function processRing(ring){
        for(let i=0;i<ring.length-1;i++){
          const lng1=ring[i][0],lat1=ring[i][1],lng2=ring[i+1][0],lat2=ring[i+1][1];
          if(typeof lng1!=='number'||typeof lat1!=='number') continue;
          const p1=ll3(lat1,lng1,radius), p2=ll3(lat2,lng2,radius);
          target.push(p1.x,p1.y,p1.z,p2.x,p2.y,p2.z);
        }
      }
      if(g.type==='Polygon') g.coordinates.forEach(processRing);
      else if(g.type==='MultiPolygon') g.coordinates.forEach(p=>p.forEach(processRing));
    });
    if(worldPos.length){
      const geom=new THREE.BufferGeometry();
      geom.setAttribute('position',new THREE.Float32BufferAttribute(worldPos,3));
      globe.add(new THREE.LineSegments(geom,new THREE.LineBasicMaterial({color:0x8dd5ff,transparent:true,opacity:0.6,blending:THREE.AdditiveBlending,depthWrite:false})));
    }
    if(brPos.length){
      const geom=new THREE.BufferGeometry();
      geom.setAttribute('position',new THREE.Float32BufferAttribute(brPos,3));
      globe.add(new THREE.LineSegments(geom,new THREE.LineBasicMaterial({color:0xffffff,transparent:true,opacity:1,blending:THREE.AdditiveBlending,depthWrite:false})));
    }
  }

  function renderLandDots(features){
    const dots=[], STEP=0.9;
    features.forEach(f=>{
      const g=f.geometry; if(!g) return;
      let minLng=180,maxLng=-180,minLat=90,maxLat=-90;
      (function visit(coords){coords.forEach(c=>{
        if(typeof c[0]==='number'){ if(c[0]<minLng)minLng=c[0]; if(c[0]>maxLng)maxLng=c[0]; if(c[1]<minLat)minLat=c[1]; if(c[1]>maxLat)maxLat=c[1]; }
        else visit(c);
      });})(g.coordinates);
      for(let lat=minLat;lat<=maxLat;lat+=STEP)for(let lng=minLng;lng<=maxLng;lng+=STEP){
        if(pointInFeature(lng,lat,g)){ const p=ll3(lat,lng,1.002); dots.push(p.x,p.y,p.z); }
      }
    });
    if(!dots.length) return;
    const geom=new THREE.BufferGeometry();
    geom.setAttribute('position',new THREE.Float32BufferAttribute(dots,3));
    globe.add(new THREE.Points(geom,new THREE.PointsMaterial({color:0x9ad8ff,size:0.014,sizeAttenuation:true,transparent:true,opacity:1,depthWrite:false})));
  }

  // Fallback (sem servidor / world.json bloqueado): contornos dos continentes a partir de LAND_POLY
  function renderFallbackLand(){
    if(typeof LAND_POLY==='undefined') return;
    const pos=[];
    LAND_POLY.forEach(flat=>{
      for(let i=0;i+3<flat.length;i+=2){
        const p1=ll3(flat[i+1],flat[i],1.008), p2=ll3(flat[i+3],flat[i+2],1.008);
        pos.push(p1.x,p1.y,p1.z,p2.x,p2.y,p2.z);
      }
    });
    if(!pos.length) return;
    const geom=new THREE.BufferGeometry();
    geom.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
    globe.add(new THREE.LineSegments(geom,new THREE.LineBasicMaterial({color:0x8dd5ff,transparent:true,opacity:0.55,blending:THREE.AdditiveBlending,depthWrite:false})));
  }

  function pointInFeature(lng,lat,geometry){
    if(geometry.type==='Polygon') return pointInPolygon(lng,lat,geometry.coordinates);
    if(geometry.type==='MultiPolygon'){
      for(let i=0;i<geometry.coordinates.length;i++) if(pointInPolygon(lng,lat,geometry.coordinates[i])) return true;
    }
    return false;
  }
  function pointInPolygon(lng,lat,polygon){
    if(!pointInRing(lng,lat,polygon[0])) return false;
    for(let i=1;i<polygon.length;i++) if(pointInRing(lng,lat,polygon[i])) return false;
    return true;
  }
  function pointInRing(lng,lat,ring){
    let inside=false;
    for(let i=0,j=ring.length-1;i<ring.length;j=i++){
      const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1];
      const intersect=((yi>lat)!==(yj>lat))&&(lng<(xj-xi)*(lat-yi)/(yj-yi)+xi);
      if(intersect) inside=!inside;
    }
    return inside;
  }

  // ---- Arcos: do centro (UFG) para as cidades parceiras (CITIES) ----
  const ARC_SEGMENTS=40;
  const arcCurves=[];
  function bezierPt(a,b,m,t){
    return new THREE.Vector3(
      (1-t)*(1-t)*a.x+2*(1-t)*t*m.x+t*t*b.x,
      (1-t)*(1-t)*a.y+2*(1-t)*t*m.y+t*t*b.y,
      (1-t)*(1-t)*a.z+2*(1-t)*t*m.z+t*t*b.z
    );
  }
  const destPts=CITIES.map(c=>ll3(c.lat,c.lon,1.012));
  const arcLinePositions=[];
  destPts.forEach(end=>{
    const start=center.clone();
    const dist=start.distanceTo(end);
    const mid=start.clone().add(end).multiplyScalar(0.5);
    if(mid.length()<0.05) mid.set(0,1,0);
    mid.normalize().multiplyScalar(1+dist*0.3);
    const pts=[]; for(let i=0;i<=ARC_SEGMENTS;i++) pts.push(bezierPt(start,end,mid,i/ARC_SEGMENTS));
    arcCurves.push(pts);
    for(let i=0;i<pts.length-1;i++){ arcLinePositions.push(pts[i].x,pts[i].y,pts[i].z,pts[i+1].x,pts[i+1].y,pts[i+1].z); }
  });
  const linesGeom=new THREE.BufferGeometry();
  linesGeom.setAttribute('position',new THREE.Float32BufferAttribute(arcLinePositions,3));
  globe.add(new THREE.LineSegments(linesGeom,new THREE.LineBasicMaterial({color:0x7dcfff,transparent:true,opacity:0.28,blending:THREE.AdditiveBlending,depthWrite:false})));

  // pontos das cidades destino
  const dotPositions=new Float32Array(destPts.length*3);
  destPts.forEach((p,i)=>{ dotPositions[i*3]=p.x; dotPositions[i*3+1]=p.y; dotPositions[i*3+2]=p.z; });
  const dotsGeom=new THREE.BufferGeometry();
  dotsGeom.setAttribute('position',new THREE.BufferAttribute(dotPositions,3));
  globe.add(new THREE.Points(dotsGeom,new THREE.PointsMaterial({color:0x7dcfff,size:0.018,sizeAttenuation:true,transparent:true,opacity:0.95,blending:THREE.AdditiveBlending,depthWrite:false})));

  // partículas viajantes nos arcos
  const particlesPerArc=2;
  const particlePositions=new Float32Array(destPts.length*particlesPerArc*3);
  const particleState=[];
  for(let i=0;i<destPts.length;i++) for(let j=0;j<particlesPerArc;j++){
    particleState.push({arcIdx:i,t:(i*0.13+j*0.5)%1,dir:j===0?1:-1,speed:0.004+((i*7)%5)*0.0012});
  }
  const pGeom=new THREE.BufferGeometry();
  pGeom.setAttribute('position',new THREE.BufferAttribute(particlePositions,3));
  globe.add(new THREE.Points(pGeom,new THREE.PointsMaterial({color:0xffffff,size:0.028,sizeAttenuation:true,transparent:true,opacity:1,blending:THREE.AdditiveBlending,depthWrite:false})));
  const posAttr=pGeom.attributes.position;

  // orientação inicial: encara o centro
  const gHyp=Math.sqrt(center.x*center.x+center.z*center.z);
  globe.rotation.y=-Math.atan2(center.x,center.z);
  globe.rotation.x=Math.atan2(center.y,gHyp);

  // ---- Interação (arrastar) ----
  let isDragging=false,prevX=0,prevY=0,velX=0,velY=0,autoRotate=true,autoTimer=null;
  function onDown(e){ isDragging=true; const t=e.touches?e.touches[0]:e; prevX=t.clientX; prevY=t.clientY; autoRotate=false; clearTimeout(autoTimer); }
  function onMove(e){
    if(!isDragging) return;
    if(e.preventDefault&&e.cancelable) e.preventDefault();
    const t=e.touches?e.touches[0]:e, dx=t.clientX-prevX, dy=t.clientY-prevY;
    globe.rotation.y+=dx*0.006; globe.rotation.x+=dy*0.006;
    globe.rotation.x=Math.max(-1.2,Math.min(1.2,globe.rotation.x));
    velX=dx*0.006; velY=dy*0.006; prevX=t.clientX; prevY=t.clientY;
  }
  function onUp(){ if(!isDragging) return; isDragging=false; autoTimer=setTimeout(()=>{autoRotate=true;},2500); }
  canvas.addEventListener('mousedown',onDown);
  window.addEventListener('mousemove',onMove);
  window.addEventListener('mouseup',onUp);
  canvas.addEventListener('touchstart',onDown,{passive:true});
  window.addEventListener('touchmove',onMove,{passive:false});
  window.addEventListener('touchend',onUp);

  function resize(){
    const rect=canvas.getBoundingClientRect();
    if(rect.width===0||rect.height===0) return;
    const aspect=rect.width/rect.height;
    camera.aspect=aspect;
    camera.position.z=aspect<1?GLOBE_Z/aspect:GLOBE_Z;
    camera.updateProjectionMatrix();
    renderer.setSize(rect.width,rect.height,false);
  }
  window.addEventListener('resize',resize);
  setTimeout(resize,50); setTimeout(resize,300);

  // ---- Tour cinematográfico ----
  function rotForLatLng(lat,lng){ const p=ll3(lat,lng,1); const hyp=Math.sqrt(p.x*p.x+p.z*p.z); return {rx:Math.atan2(p.y,hyp),ry:-Math.atan2(p.x,p.z)}; }
  /* tour pelo Cerrado, não mais pelo mundo: Goiânia -> Chapada dos Veadeiros -> Araguaia -> sul de Goiás */
  const tourTargets=[ rotForLatLng(HUB.lat,HUB.lon), rotForLatLng(-14.2,-47.6), rotForLatLng(-12.8,-51.0), rotForLatLng(-17.8,-50.9) ];
  const TOUR_LEG_DURATION=9.0;
  let tourIdx=0,tourT=0;
  function lerpAngle(a,b,t){ const diff=((b-a+Math.PI)%(2*Math.PI)+2*Math.PI)%(2*Math.PI)-Math.PI; return a+diff*t; }
  function easeInOutQuad(t){ return t<0.5?2*t*t:1-Math.pow(-2*t+2,2)/2; }

  let tt=0,rafId=null,destroyed=false;
  function animate(){
    if(destroyed) return;
    if(!document.body.contains(canvas)){ api.destroy(); return; }   // saiu da view
    rafId=requestAnimationFrame(animate);
    tt+=0.016;
    if(!isDragging){
      if(Math.abs(velX)>0.0002||Math.abs(velY)>0.0002){
        globe.rotation.y+=velX; globe.rotation.x+=velY;
        globe.rotation.x=Math.max(-1.2,Math.min(1.2,globe.rotation.x));
        velX*=0.95; velY*=0.95;
      } else if(autoRotate){
        tourT+=0.016/TOUR_LEG_DURATION;
        if(tourT>=1){ tourT=0; tourIdx=(tourIdx+1)%tourTargets.length; }
        const eased=easeInOutQuad(tourT);
        const cur=tourTargets[tourIdx], next=tourTargets[(tourIdx+1)%tourTargets.length];
        globe.rotation.x=lerpAngle(cur.rx,next.rx,eased);
        globe.rotation.y=lerpAngle(cur.ry,next.ry,eased);
      }
    }
    for(let i=0;i<particleState.length;i++){
      const ps=particleState[i];
      ps.t+=ps.dir*ps.speed;
      if(ps.t>=1){ ps.t=1; ps.dir=-1; } else if(ps.t<=0){ ps.t=0; ps.dir=1; }
      const curve=arcCurves[ps.arcIdx];
      const idx=Math.min(Math.floor(ps.t*(curve.length-1)),curve.length-1);
      const pt=curve[idx];
      particlePositions[i*3]=pt.x; particlePositions[i*3+1]=pt.y; particlePositions[i*3+2]=pt.z;
    }
    posAttr.needsUpdate=true;
    for(let i=0;i<pulseRings.length;i++){
      const r=pulseRings[i], phase=(tt*0.4+r.userData.offset)%1, sc=1+phase*6;
      r.scale.set(sc,sc,1); r.material.opacity=0.75*(1-phase);
    }
    const gp=1+Math.sin(tt*2)*0.15; centerGlow.scale.set(gp,gp,gp);
    renderer.render(scene,camera);
  }

  const api={
    destroy(){
      if(destroyed) return;
      destroyed=true;
      if(rafId) cancelAnimationFrame(rafId);
      clearTimeout(autoTimer);
      canvas.removeEventListener('mousedown',onDown);
      window.removeEventListener('mousemove',onMove);
      window.removeEventListener('mouseup',onUp);
      canvas.removeEventListener('touchstart',onDown);
      window.removeEventListener('touchmove',onMove);
      window.removeEventListener('touchend',onUp);
      window.removeEventListener('resize',resize);
      try{ renderer.dispose(); }catch(_){}
      if(HERO_GLOBE===api) HERO_GLOBE=null;
    }
  };

  resize();
  if(REDUCE){ renderer.render(scene,camera); }   // sem animação: render estático
  else animate();
  return api;
}

