function buildNav(){
  document.getElementById('nav').innerHTML=NAV.map(g=>{
    const items=g.items.filter(([id])=>id!=='edicao'||podeEditar(PAPEL_ATUAL));
    if(!items.length) return '';
    return `<div class="nav-group"><div class="nav-label">${g.grp}</div>
    ${items.map(([id,ic,label,isnew])=>`<div class="nav-item" data-view="${id}" title="${label}" role="button" tabindex="0">
       <span class="ic">${ICONS[id]||ic||''}</span><span class="txt">${label}</span>${isnew?'<span class="badge-new">NOVO</span>':''}</div>`).join('')}
    </div>`;
  }).join('');
  document.querySelectorAll('.nav-item').forEach(n=>{
    n.addEventListener('click',()=>go(n.dataset.view,true));
    n.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); go(n.dataset.view,true); } });
  });
  traduzir(document.getElementById('nav'));
}

/* porUsuario = a troca partiu de um clique ou de um Enter no menu (e não do
   boot). Só nesse caso o foco se move: no boot a janela de abertura está por
   cima, e roubar o foco dela seria pior que o silêncio. */
function go(view,porUsuario){
  /* escolher uma tela fecha a gaveta; sem devolver o foco ao hamburguer,
     porque o foco vai para o conteudo novo. */
  try{ if(typeof gaveta!=='undefined') gaveta.fechar(false); }catch(_){}
  if(view==='edicao'&&!podeEditar(PAPEL_ATUAL)){ console.warn('[go] acesso à edição negado · papel:',PAPEL_ATUAL); view='geral'; }
  const v=VIEWS[view];if(!v)return;
  document.querySelectorAll('.nav-item').forEach(n=>{const at=n.dataset.view===view;n.classList.toggle('active',at);n.setAttribute('aria-current',at?'page':'false');});
  document.getElementById('topTitle').textContent=v.title;
  document.getElementById('main').innerHTML=`
    <div class="view-head">
      <div class="crumb">${v.crumb}</div>
      <h1>${v.title}</h1>
      <p>${v.desc}</p>
    </div>
    ${v.render()}
    <div class="footer-note">Dados de demonstração · Projeto de Extensão Flore-Ser · PROEC/UFG · 2026 · <a href="https://www.instagram.com/floreser.ufg" target="_blank" rel="noopener">@floreser.ufg</a> · <a href="mailto:floreser.ufg@gmail.com">floreser.ufg@gmail.com</a></div>`;
  window.scrollTo({top:0,behavior:'instant'});
  /* E.1 entrada de tela. A classe precisa ser RETIRADA, o layout lido para
     forcar o reflow, e so entao recolocada; sem o void el.offsetWidth o
     navegador agrupa as duas mudancas no mesmo quadro e nada anima.
     Sob prefers-reduced-motion o CSS zera a animacao (a classe continua
     sendo posta, mas nao produz movimento). */
  const _m=document.getElementById('main');
  if(_m){ _m.classList.remove('view-enter'); void _m.offsetWidth; _m.classList.add('view-enter'); }
  // ativar interações específicas da view
  if(view==='mapa')initMapView();
  if(view==='geral'||view==='mob'||view==='conv')wireMapNodes(document.getElementById('main'));
  /* globo do hero removido: agora é uma foto (assets/img/hero-cerrado.jpg) */
  if(view==='geral')criarMapaReal('mapaGeral',{scroll:false,zoomControl:false,fit:'acao'});
  if(view==='prod')initProd();
  if(view==='galeria')initGaleria();
  if(view==='espacos')initEspacos();
  if(view==='edicao')initEdicao();
  traduzir(document.getElementById('main'));
  traduzir(document.getElementById('topTitle'));

  /* A tela trocou por inteiro. Quem enxerga percebe pelo conteúdo novo; para
     o resto é preciso dizer, e são três coisas distintas: nenhuma substitui
     a outra. O título do documento orienta aba e histórico; o anúncio na
     região de status fala agora; o foco define de onde o Tab continua.
     Sem o foco, ele continuaria do item do menu e o usuário reatravessaria a
     navegação inteira a cada tela. */
  const _semTags=s=>String(s||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
  document.title=`${_semTags(v.title)} · Flore-Ser · Painel de Extensão Socioambiental · UFG`;
  if(porUsuario){
    const an=document.getElementById('anuncioTela');
    if(an) an.textContent=`${_semTags(v.title)}. ${_semTags(v.desc)}`;
    /* o h1 da tela é o alvo certo: anuncia o nome dela ao receber o foco.
       O anel só aparece se a navegação foi por teclado, porque :focus-visible não
       casa em foco movido por programa depois de um clique de mouse. */
    const h=document.querySelector('#main .view-head h1');
    if(h){ h.setAttribute('tabindex','-1'); h.focus({preventScroll:true}); }
    else { document.getElementById('main')?.focus({preventScroll:true}); }
  }
}

/* ===== interações: mapa-múndi ===== */
function wireMapNodes(scope){
  const tip=document.getElementById('mapTip');
  scope.querySelectorAll('.node-c').forEach(g=>{
    const c=CITIES[+g.dataset.i]; if(!c) return;
    /* O nó passa a ser um controle de verdade: alcançável por Tab e com nome
       que já carrega os dois números. Quem navega por teclado ou por leitor
       de tela recebe o dado pelo NOME, sem depender do balão, que é
       recurso visual e continua sendo só isso. */
    g.setAttribute('tabindex','0');
    g.setAttribute('role','button');
    g.setAttribute('aria-label',`${c.city}, ${c.cont}. ${c.out} mudas plantadas, ${c.in} participantes.`);

    const encher=()=>{
      tip.innerHTML=`<b>${c.city}</b><div class="r"><span>${c.cont}</span></div>
        <div class="r"><span>Mudas plantadas</span><b style="color:var(--green)">${c.out}</b></div>
        <div class="r"><span>Participantes</span><b style="color:var(--blue)">${c.in}</b></div>`;
      traduzir(tip);
    };
    const posicionar=(x,y)=>{ tip.style.left=x+'px'; tip.style.top=y+'px'; tip.style.opacity='1'; };
    const sumir=()=>{ tip.style.opacity='0'; };

    g.addEventListener('mousemove',e=>{ encher(); posicionar(e.clientX+14,e.clientY-10); });
    g.addEventListener('mouseleave',sumir);
    /* o foco espelha o ponteiro. A diferença é a âncora: sem cursor de onde
       partir, o balão nasce colado à borda do próprio nó. */
    g.addEventListener('focus',()=>{ const r=g.getBoundingClientRect(); encher(); posicionar(r.right+10,r.top-6); });
    g.addEventListener('blur',sumir);

    const abrir=()=>{
      if(!document.getElementById('mapDetail')) return;
      focusCity(+g.dataset.i);
      /* o detalhe abre longe do foco, abaixo do mapa: sem avisar, a ativação
         por teclado não produz nenhum sinal perceptível. */
      const an=document.getElementById('anuncioTela');
      if(an) an.textContent=`${c.city}: ${c.out} mudas plantadas, ${c.in} participantes. Detalhe aberto abaixo do mapa.`;
    };
    g.addEventListener('click',abrir);
    g.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); abrir(); } });
  });
}
function focusCity(gi){
  const host=document.getElementById('mapDetail'); if(!host)return;
  const c=CITIES[gi];
  document.querySelectorAll('#mapBox .node-c').forEach(n=>n.classList.toggle('sel',+n.dataset.i===gi));
  const mx=Math.max(c.out,c.in,1);
  host.innerHTML=card(`${c.city}`,c.cont,
    `<div style="display:flex;gap:26px;flex-wrap:wrap;align-items:center">
       <div class="mini-stat">
         <div><span class="n" style="color:var(--green)">${c.out}</span><span class="l">Mudas plantadas</span></div>
         <div><span class="n" style="color:var(--blue)">${c.in}</span><span class="l">Participantes</span></div>
         <div><span class="n">${c.out+c.in}</span><span class="l">Total</span></div>
       </div>
       <div style="flex:1;min-width:240px">
         <div class="gb-line" style="margin-bottom:7px"><span class="tag">Mudas</span><div class="gb-track"><div class="gb-out" style="height:100%;width:${(c.out/mx*100).toFixed(0)}%"></div></div><span class="gb-v">${c.out}</span></div>
         <div class="gb-line"><span class="tag">Partic.</span><div class="gb-track"><div class="gb-in" style="height:100%;width:${(c.in/mx*100).toFixed(0)}%"></div></div><span class="gb-v">${c.in}</span></div>
       </div>
       <button class="pill" onclick="clearFocus()">Limpar seleção</button>
     </div>`);
  traduzir(host);
}
function clearFocus(){
  document.querySelectorAll('#mapBox .node-c').forEach(n=>n.classList.remove('sel'));
  const host=document.getElementById('mapDetail'); if(host)host.innerHTML='';
}
function initMapView(){
  criarMapaReal('mapaReal',{scroll:false,fit:'acao'});
  renderMapAux('all');
  document.querySelectorAll('#mapVis .pill').forEach(p=>p.addEventListener('click',()=>{
    if(p.dataset.fit){
      document.querySelectorAll('#mapVis .pill[data-fit]').forEach(x=>x.classList.remove('on'));
      p.classList.add('on'); enquadrarMapa('mapaReal',p.dataset.fit);
    }else if(p.dataset.tile){
      document.querySelectorAll('#mapVis .pill[data-tile]').forEach(x=>x.classList.remove('on'));
      p.classList.add('on'); trocarEstiloMapa(p.dataset.tile);
    }
  }));
  document.querySelectorAll('#mapFilters .pill').forEach(p=>p.addEventListener('click',()=>{
    document.querySelectorAll('#mapFilters .pill').forEach(x=>x.classList.remove('on'));
    p.classList.add('on'); _filtroReg=p.dataset.cont;
    aplicarFiltrosMapa('mapaReal'); renderMapAux(_filtroReg);
  }));
  document.querySelectorAll('#mapStatus .pill').forEach(p=>p.addEventListener('click',()=>{
    document.querySelectorAll('#mapStatus .pill').forEach(x=>x.classList.remove('on'));
    p.classList.add('on'); _filtroSt=p.dataset.st;
    aplicarFiltrosMapa('mapaReal'); renderMapAux(_filtroReg);
  }));
}
function renderMapAux(cont){
  const cs=CITIES.filter(c=>(cont==='all'||c.cont===cont)
    &&(_filtroSt==='todos'||(_filtroSt==='realizado'?c.status==='realizado':c.status!=='realizado')));
  const feitos=cs.filter(c=>c.status==='realizado');
  const o=sum(feitos,'out'),i=sum(feitos,'in');const regs=new Set(cs.map(c=>c.cont)).size;
  document.getElementById('mapKpis').innerHTML=[
    {lbl:'Com atividade realizada',val:feitos.length+'<span style="font-size:15px;color:var(--text-3)">/'+cs.length+'</span>',accent:'green',foot:'espaços já ativados'},
    {lbl:'Ações realizadas',val:o,accent:'cyan',foot:'registradas no inventário'},
    {lbl:'Participantes',val:i,accent:'blue',foot:'em mutirões e oficinas'},
    {lbl:'Regiões',val:regs,accent:'amber',foot:cont==='all'?'de Goiânia':cont}
  ].map(k=>`<div class="kpi accent-${k.accent}"><div class="lbl">${k.lbl}</div><div class="val">${k.val}</div><div class="foot">${k.foot}</div></div>`).join('');
  const rows=cs.slice().sort((a,b)=>((b.status==='realizado')-(a.status==='realizado'))||((b.out+b.in)-(a.out+a.in))).map(c=>{
    const f=c.status==='realizado';
    return [_escHTML(c.city),_escHTML(c.cont),
      f?'<span class="chip gr">Realizada</span>':'<span class="chip">Não iniciado</span>',
      f?c.out:'·', f?c.in:'·'];
  });
  document.getElementById('mapTable').innerHTML=elTable({title:'Detalhe por espaço',sub:`${cs.length} espaços · ${feitos.length} com atividade`,
    cols:[{h:'Espaço'},{h:'Região'},{h:'Atividade'},{h:'Ações',num:true},{h:'Participantes',num:true}],rows});
  traduzir(document.getElementById('main'));
}

