/* ===== interações: exposição fotográfica ===== */
let _galItens=[],_galAtual=0,_galKeyWired=false,_galFocoAnterior=null;
function _galVisiveis(){return _galItens.filter(it=>it.style.display!=='none');}
function _galAberto(){const lb=document.getElementById('galLb');return !!lb&&!lb.hidden;}
function _galFechar(){
  const lb=document.getElementById('galLb'); if(!lb)return;
  lb.hidden=true; const im=lb.querySelector('img'); if(im)im.src='';
  document.body.style.overflow='';
  // a gaveta tambem poe inert no #main: se ela estiver aberta por baixo, o
  // inert e dela e nao pode sair junto com o lightbox.
  const m=document.getElementById('main');
  let gavetaAberta=false;
  try{ gavetaAberta=(typeof gaveta!=='undefined') && gaveta.aberta(); }catch(_){}
  if(m && !gavetaAberta) m.removeAttribute('inert');
  if(_galFocoAnterior&&document.contains(_galFocoAnterior)){_galFocoAnterior.focus();}
  _galFocoAnterior=null;
}
function _galAbrir(i){
  const lb=document.getElementById('galLb'); if(!lb)return;
  const lista=_galVisiveis(); if(!lista.length)return;
  const abrindoAgora=lb.hidden;
  _galAtual=(i+lista.length)%lista.length;
  const p=FOTOS[+lista[_galAtual].dataset.i]; if(!p)return;
  const im=lb.querySelector('img');
  im.src='assets/img/galeria/'+p.f; im.alt=p.l;
  lb.querySelector('figcaption').textContent=p.l;
  if(abrindoAgora){
    _galFocoAnterior=document.activeElement;
    lb.hidden=false;
    document.body.style.overflow='hidden';
    const m=document.getElementById('main'); if(m)m.setAttribute('inert','');
    const x=lb.querySelector('.gal-lb-x'); if(x)x.focus();
  }
}
function initGaleria(){
  const grid=document.getElementById('galGrid'); if(!grid)return;
  _galItens=Array.prototype.slice.call(grid.querySelectorAll('.gal-item'));
  document.querySelectorAll('#galFiltros .pill').forEach(p=>{
    p.setAttribute('aria-pressed',p.classList.contains('on')?'true':'false');
    p.addEventListener('click',()=>{
      document.querySelectorAll('#galFiltros .pill').forEach(x=>{x.classList.remove('on');x.setAttribute('aria-pressed','false');});
      p.classList.add('on'); p.setAttribute('aria-pressed','true');
      const t=p.dataset.tema;
      _galItens.forEach(it=>{it.style.display=(t==='todos'||it.dataset.tema===t)?'':'none';});
    });
  });
  let lb=document.getElementById('galLb');
  if(!lb){
    lb=document.createElement('div'); lb.id='galLb'; lb.className='gal-lb'; lb.hidden=true;
    lb.setAttribute('role','dialog'); lb.setAttribute('aria-modal','true'); lb.setAttribute('aria-label','Foto ampliada');
    lb.innerHTML='<button class="gal-lb-btn gal-lb-x" aria-label="Fechar">✕</button>'
      +'<button class="gal-lb-btn gal-lb-prev" aria-label="Foto anterior">‹</button>'
      +'<figure><img alt=""><figcaption></figcaption></figure>'
      +'<button class="gal-lb-btn gal-lb-next" aria-label="Próxima foto">›</button>';
    document.body.appendChild(lb);
  }
  lb.querySelector('.gal-lb-x').onclick=_galFechar;
  lb.querySelector('.gal-lb-prev').onclick=function(){_galAbrir(_galAtual-1);};
  lb.querySelector('.gal-lb-next').onclick=function(){_galAbrir(_galAtual+1);};
  lb.onclick=function(e){if(e.target===lb)_galFechar();};
  _galItens.forEach(it=>{
    it.addEventListener('click',function(){if(_galAberto())return;_galAbrir(_galVisiveis().indexOf(it));});
    it.addEventListener('keydown',function(e){
      if(_galAberto())return;
      if(e.key==='Enter'||e.key===' '){e.preventDefault();_galAbrir(_galVisiveis().indexOf(it));}
    });
  });
  if(!_galKeyWired){
    document.addEventListener('keydown',function(e){
      const l=document.getElementById('galLb'); if(!l||l.hidden)return;
      if(e.key==='Escape'){e.preventDefault();_galFechar();}
      else if(e.key==='ArrowLeft'){e.preventDefault();_galAbrir(_galAtual-1);}
      else if(e.key==='ArrowRight'){e.preventDefault();_galAbrir(_galAtual+1);}
      else if(e.key==='Tab'){ // mantém o foco dentro da janela ampliada
        const f=l.querySelectorAll('button'); if(!f.length)return;
        const pr=f[0], ul=f[f.length-1];
        if(!l.contains(document.activeElement)){e.preventDefault();pr.focus();}
        else if(e.shiftKey&&document.activeElement===pr){e.preventDefault();ul.focus();}
        else if(!e.shiftKey&&document.activeElement===ul){e.preventDefault();pr.focus();}
      }
    });
    _galKeyWired=true;
  }
}

