window.clearFocus=clearFocus; // handler inline usado no card de focusCity()

/* =========================================================
   TEMA CLARO / ESCURO (fundacao de front-end, Fase 1)
   Contrato, identico nas tres telas do Flore-Ser para o tema seguir o
   usuario entre site, painel e apresentacao:
     - atributo data-theme no <html>: ausente ou "light" = CLARO (padrao),
       "dark" = ESCURO;
     - chave FLORESER_TEMA em localStorage, valores "claro" | "escuro";
     - toda leitura e escrita em try/catch com falha silenciosa.
   A restauracao ja aconteceu na IIFE do <head> de painel.html; aqui so
   fica a alternancia. O botao vive na topbar, que nunca e reescrita.
   ========================================================= */
const CHAVE_TEMA='FLORESER_TEMA';
function temaAtual(){
  return document.documentElement.getAttribute('data-theme')==='dark'?'escuro':'claro';
}
function sincronizarBotaoTema(){
  const b=document.getElementById('btnTema'); if(!b) return;
  const escuro=temaAtual()==='escuro';
  // aria-pressed diz se o tema escuro esta LIGADO; o rotulo diz o que o
  // clique vai fazer. Os dois trocam a cada alternancia.
  // O botao e so icone, entao o title e o UNICO texto visivel dele: ele tem de
  // ser igual ao aria-label, senao o nome acessivel diverge do nome visivel e
  // quebra comando de voz (Label in Name). Nada de "Voltar ao tema claro": quem
  // chega com o escuro ja restaurado nunca esteve no claro nesta sessao.
  const rotulo = escuro ? 'Ativar tema claro' : 'Ativar tema escuro';
  b.setAttribute('aria-pressed', escuro?'true':'false');
  b.setAttribute('aria-label', rotulo);
  b.setAttribute('title', rotulo);
}
function aplicarTema(t){
  if(t==='escuro') document.documentElement.setAttribute('data-theme','dark');
  else document.documentElement.removeAttribute('data-theme');
  try{ localStorage.setItem(CHAVE_TEMA, t==='escuro'?'escuro':'claro'); }catch(e){}
  sincronizarBotaoTema();
}
document.getElementById('btnTema')?.addEventListener('click',()=>{
  aplicarTema(temaAtual()==='escuro'?'claro':'escuro');
});
sincronizarBotaoTema();

/* =========================================================
   GAVETA DE NAVEGACAO (761px a 1180px e abaixo)
   Nessa faixa a sidebar e um trilho de 62px so com icones; a gaveta e o
   estado ABERTO desse trilho. O trilho de <=760px ja funcionava desde a
   rodada de 26/07 e nao foi refeito, so estendido ate 1180px.
   ========================================================= */
const gaveta={
  el(){ return document.getElementById('sidebar'); },
  botao(){ return document.getElementById('btnMenu'); },
  veu(){ return document.getElementById('navVeu'); },
  aberta(){ const s=this.el(); return !!s && s.classList.contains('open'); },
  // Focaveis REAIS da gaveta, na ordem do DOM. O filtro por offsetParent e
  // obrigatorio: o #collapseBtn e o primeiro do documento dentro da
  // .sidebar, mas display:none em toda a faixa em que a gaveta existe
  // (styles.css, @media max-width:1180px). Sem o filtro, pri era um botao
  // invisivel, pri.focus() virava no-op e o ciclo nao fechava em nenhuma das
  // duas direcoes. O filtro tambem cobre item de menu que um futuro filtro
  // de permissao venha a esconder.
  focaveis(){
    const s=this.el(); if(!s) return [];
    return Array.prototype.slice.call(s.querySelectorAll('.nav-item,.side-foot a,.collapse-btn'))
      .filter(el=>el.offsetParent!==null && !el.hasAttribute('disabled') && el.tabIndex>-1);
  },
  abrir(){
    const s=this.el(), b=this.botao(), v=this.veu(); if(!s) return;
    s.classList.add('open');
    if(v) v.hidden=false;
    if(b){ b.setAttribute('aria-expanded','true'); b.setAttribute('aria-label','Fechar menu de navegação'); }
    // segunda camada: com o veu no ar, o conteudo debaixo dele nao existe
    // para o teclado nem para o leitor de tela. Mesmo padrao do lightbox da
    // galeria (_galAbrir), que ja fazia isto certo.
    const m=document.getElementById('main'); if(m) m.setAttribute('inert','');
    const primeiro=s.querySelector('.nav-item');
    if(primeiro) primeiro.focus();
  },
  fechar(devolverFoco){
    const s=this.el(), b=this.botao(), v=this.veu(); if(!s) return;
    const estava=s.classList.contains('open');
    s.classList.remove('open');
    if(v) v.hidden=true;
    if(b){ b.setAttribute('aria-expanded','false'); b.setAttribute('aria-label','Abrir menu de navegação'); }
    // o lightbox tambem usa inert no #main: so devolve se ele nao estiver
    // aberto por baixo, senao a gaveta destravaria o conteudo dele.
    const m=document.getElementById('main');
    if(m && !_galAberto()) m.removeAttribute('inert');
    // devolve o foco ao botao que abriu, para o teclado nao ficar orfao
    if(estava && devolverFoco && b) b.focus();
  },
  alternar(){ this.aberta()?this.fechar(true):this.abrir(); }
};
document.getElementById('btnMenu')?.addEventListener('click',()=>gaveta.alternar());
document.getElementById('navVeu')?.addEventListener('click',()=>gaveta.fechar(true));
document.addEventListener('keydown',e=>{
  if(e.key==='Escape' && gaveta.aberta()){ e.preventDefault(); gaveta.fechar(true); }
});
/* prende o Tab dentro da gaveta enquanto ela esta aberta (foco em ciclo) */
document.addEventListener('keydown',e=>{
  if(e.key!=='Tab' || !gaveta.aberta()) return;
  const focaveis=gaveta.focaveis();
  // com menos de dois focaveis nao ha ciclo a montar: melhor deixar o Tab
  // passar do que cancelar a tecla e prender o usuario numa gaveta muda.
  if(focaveis.length<2) return;
  const pri=focaveis[0], ult=focaveis[focaveis.length-1];
  const foco=document.activeElement;
  if(e.shiftKey && foco===pri){ e.preventDefault(); ult.focus(); }
  else if(!e.shiftKey && foco===ult){ e.preventDefault(); pri.focus(); }
  // o foco escapou da gaveta (veio da topbar, por exemplo): traz de volta
  else if(!gaveta.el().contains(foco)){ e.preventDefault(); (e.shiftKey?ult:pri).focus(); }
});
/* se a janela crescer acima do breakpoint, a gaveta deixa de fazer sentido */
window.addEventListener('resize',()=>{
  if(window.innerWidth>1180 && gaveta.aberta()) gaveta.fechar(false);
});

