async function carregarERenderizar(){
  try{
    const d=await carregarDados();
    if(d){
      aplicarDados(d);
      const ativa=document.querySelector('.nav-item.active');
      go(ativa?ativa.dataset.view:'geral'); // re-render da view atual com dados do banco
    }
  }catch(e){ console.warn('[boot] falha ao carregar dados; mantendo embutidos.',e); }
}

function traduzErroAuth(e){
  const c=(e&&e.code)||'';
  if(c.includes('popup-closed')||c.includes('cancelled-popup')) return 'Login cancelado.';
  if(c.includes('popup-blocked')) return 'O navegador bloqueou o popup. Permita popups e tente de novo.';
  if(c.includes('network')) return 'Falha de rede. Verifique a conexão.';
  if(c.includes('unauthorized-domain')) return 'Domínio não autorizado no Firebase Auth.';
  return 'Não foi possível entrar. Tente novamente.';
}

function aplicarUsuario(user,papel,authMod){
  PAPEL_ATUAL=papel||'leitor'; USER_ATUAL=user;
  document.getElementById('fbBtn')?.removeAttribute('hidden');
  const av=document.querySelector('.avatar'); if(!av) return;
  const nome=user.displayName||user.email||'Usuário';
  const ini=(nome.trim().split(/\s+/).map(s=>s[0]).slice(0,2).join('')||'··').toUpperCase();
  av.textContent=ini; av.title=nome; av.classList.add('logged');
  let menu=document.getElementById('userMenu');
  if(!menu){
    menu=document.createElement('div'); menu.className='user-menu'; menu.id='userMenu'; menu.hidden=true;
    document.body.appendChild(menu);
    document.addEventListener('click',()=>{ menu.hidden=true; });
  }
  menu.innerHTML=`<div class="um-nome">${nome}</div><div class="um-mail">${user.email||''}</div>`+
    `<div class="um-papel">Papel: ${papel||'leitor'}</div><button class="um-sair" id="btnSair">Sair</button>`;
  av.onclick=(e)=>{ e.stopPropagation(); menu.hidden=!menu.hidden; };
  menu.querySelector('#btnSair').onclick=async()=>{ menu.hidden=true; await authMod.sair(); };
  traduzir(menu);
}

/* ===== boot: modo demo (seeds) ou modo Firebase (login obrigatório) ===== */
(async()=>{
  const gate=document.getElementById('authGate');
  let authMod=null;
  try{ authMod=await import('./assets/js/auth.js'); }
  catch(e){ console.info('[boot] Firebase indisponível: modo demonstração.'); }

  if(!authMod || !authMod.USAR_FIREBASE){
    // modo demonstração: sem login, lê seeds/embutidos
    if(gate) gate.hidden=true;
    buildNav();
    go('geral');
    carregarERenderizar();
    return;
  }

  // modo Firebase: o painel só aparece após login (regras exigem isAuth())
  if(gate){
    gate.hidden=false;
    /* a janela de login cobre tudo: o resto fica inerte e o foco entra nela. */
    [document.querySelector('.topbar'),document.querySelector('.shell')]
      .filter(Boolean).forEach(e=>e.setAttribute('inert',''));
    setTimeout(()=>{ document.getElementById('btnLogin')?.focus(); },60);
  }
  const msg=document.getElementById('authMsg');
  const btn=document.getElementById('btnLogin');
  if(btn) btn.onclick=async()=>{
    if(msg) msg.textContent=''; btn.disabled=true;
    try{ await authMod.entrarComGoogle(); }
    catch(e){ if(msg) msg.textContent=traduzErroAuth(e); }
    finally{ btn.disabled=false; }
  };
  // acesso de demonstração: 3 perfis (PRPG/SRI/PPG) via e-mail+senha
  document.querySelectorAll('.demo-btn').forEach(b=>b.onclick=async()=>{
    if(msg) msg.textContent=''; b.disabled=true;
    try{ await authMod.entrarComEmail(b.dataset.demo,'EcoaDemo2026'); }
    catch(e){ if(msg) msg.textContent=traduzErroAuth(e); }
    finally{ b.disabled=false; }
  });

  /* o inert do fundo acompanha a janela de login: some quando ela some e
     volta quando ela volta (logout). Deixá-lo para trás travaria o painel
     inteiro para teclado e leitor de tela, sem nenhum sinal na tela. */
  const _fundoLogin=()=>[document.querySelector('.topbar'),document.querySelector('.shell')].filter(Boolean);
  let montado=false;
  authMod.observarAuth(async(user)=>{
    if(user){
      if(gate) gate.hidden=true;
      _fundoLogin().forEach(e=>e.removeAttribute('inert'));
      const papel=await authMod.obterPapel(user).catch(()=>'leitor');
      aplicarUsuario(user,papel,authMod);
      if(!montado){ montado=true; buildNav(); go('geral'); }
      await carregarERenderizar();
    } else {
      if(gate){
        gate.hidden=false;
        _fundoLogin().forEach(e=>e.setAttribute('inert',''));
        setTimeout(()=>{ document.getElementById('btnLogin')?.focus(); },60);
      }
    }
  });
})();

