function gerarRelatorioPDF(){
  const root=document.getElementById('reportRoot');
  root.innerHTML=buildReport();
  document.body.classList.add('printing-report');
  setTimeout(()=>{window.print();},60);
}
window.addEventListener('afterprint',()=>{
  document.body.classList.remove('printing-report');
});

/* botão do topbar (script é type="module": ligamos por id, não por onclick inline) */
document.getElementById('btnRelatorio')?.addEventListener('click', gerarRelatorioPDF);

/* =========================================================
   Janela de boas-vindas (abertura do sistema)
   Reaproveita o globo 3D do hero (buildHeroGlobe) + marca Flore-Ser.
   Fecha por botão, clique fora ou Esc; destrói o globo ao sair.
   ========================================================= */
function initWelcome(){
  const ov=document.getElementById('welcome'); if(!ov) return;
  try{ if(typeof traduzir==='function') traduzir(ov); }catch(_){}
  const cv=document.getElementById('welcomeGlobe');
  let wg=null, closed=false;
  if(cv && typeof ensureGlobeLibs==='function'){
    ensureGlobeLibs().then(()=>{ if(!closed && document.body.contains(cv)) wg=buildHeroGlobe(cv); }).catch(()=>{});
  }
  /* Enquanto a janela esta aberta, o resto da pagina fica inerte: sem isto o
     Tab passeia pela topbar e pelo menu por baixo do veu, e o leitor de tela
     le a pagina inteira como se a janela nao existisse. Mesmo recurso que o
     lightbox da galeria e a gaveta ja usam. */
  const fundo=[
    document.querySelector('.skip-link'),
    document.querySelector('.topbar'),
    document.querySelector('.shell')
  ].filter(Boolean);
  fundo.forEach(e=>e.setAttribute('inert',''));
  /* o foco entra na janela: sem isto ele fica no <body> e o primeiro Tab cai
     em lugar nenhum. O botao de entrar e a acao principal. */
  setTimeout(()=>{ document.getElementById('welcomeEnter')?.focus(); }, 60);

  function fechar(){
    if(closed) return; closed=true;
    ov.classList.add('closing');
    try{ wg && wg.destroy(); }catch(_){}
    document.removeEventListener('keydown',onKey);
    fundo.forEach(e=>e.removeAttribute('inert'));
    /* devolve o foco ao conteudo: a janela vai sumir, e o foco nao pode
       sumir junto para o <body>. */
    document.getElementById('main')?.focus({preventScroll:true});
    setTimeout(()=>{ ov.remove(); }, 470);
  }
  function onKey(e){ if(e.key==='Escape') fechar(); }
  document.getElementById('welcomeClose')?.addEventListener('click',fechar);
  document.getElementById('welcomeEnter')?.addEventListener('click',fechar);
  ov.addEventListener('click',e=>{ if(e.target===ov || (e.target.classList&&e.target.classList.contains('welcome-bg'))) fechar(); });
  document.addEventListener('keydown',onKey);
}
initWelcome();

