let _editCol='convenios', _editDados=[];

function _escAttr(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');}
function _escHTML(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function _campoLabel(cfg,k){const f=cfg.campos.find(x=>x.k===k);return f?f.l:k;}
function _fmtData(v){
  if(!v) return '·';
  const d = v.toDate ? v.toDate() : (v.seconds!=null ? new Date(v.seconds*1000) : new Date(v));
  return isNaN(d) ? '·' : d.toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
}
function _fmtVal(cfg,k,v){
  const f=cfg.campos.find(x=>x.k===k);
  if(f&&f.t==='ts') return _fmtData(v);
  if(f&&f.t==='anexos') return (Array.isArray(v)&&v.length)?('📎 '+v.length):'·';
  if(v==null||v==='') return '·';
  if(f&&f.t==='bool') return v?'Sim':'Não';
  if(f&&f.ops){const o=f.ops.find(o=>o[0]===v);if(o)return o[1];}
  if(Array.isArray(v)) return _escHTML(v.join(', '));
  if(f&&f.k==='valor') return 'R$ '+Number(v).toLocaleString('pt-BR');
  return _escHTML(v);
}

function initEdicao(){
  const root=document.getElementById('editRoot'); if(!root) return;
  if(!podeEditar(PAPEL_ATUAL)){ root.innerHTML='<div class="edit-erro">Acesso restrito a gestores.</div>'; return; }
  const tabs=Object.entries(EDIT_COLS).map(([col,cfg])=>`<button class="edit-tab${col===_editCol?' on':''}" data-col="${col}">${cfg.titulo}</button>`).join('');
  root.innerHTML=`
    <div class="edit-tabs">${tabs}</div>
    <div class="edit-toolbar">
      <button class="edit-new" id="editNew">+ Novo registro</button>
      <span class="edit-status" id="editStatus"></span>
    </div>
    <div id="editFormWrap"></div>
    <div id="editList" class="edit-list">Carregando…</div>`;
  root.querySelectorAll('.edit-tab').forEach(b=>b.onclick=()=>{ const w=document.getElementById('editFormWrap'); if(w&&w.innerHTML.trim()&&!confirm('Há um formulário aberto. Descartar e trocar de aba?')) return; _editCol=b.dataset.col; initEdicao(); });
  document.getElementById('editNew').onclick=()=>_editForm(null);
  _editCarregarLista();
}

async function _editCarregarLista(){
  const listEl=document.getElementById('editList'); if(!listEl) return;
  const cfg=EDIT_COLS[_editCol];
  try{ _editDados=await lerColecao(_editCol); }
  catch(e){ listEl.innerHTML=`<div class="edit-erro">Não foi possível ler os dados: ${_escHTML(e.message)}</div>`; return; }
  const ativos=_editDados.filter(d=>!d.deleted_at);
  if(!ativos.length){ listEl.innerHTML='<div class="edit-vazio">Nenhum registro. Clique em “+ Novo registro”.</div>'; return; }
  const cols=cfg.lista;
  listEl.innerHTML=`<table class="edit-table"><thead><tr>${cols.map(c=>`<th>${_campoLabel(cfg,c)}</th>`).join('')}<th></th></tr></thead><tbody>${
    ativos.map(item=>`<tr>${cols.map(c=>`<td>${_fmtVal(cfg,c,item[c])}</td>`).join('')}<td class="edit-acoes">
      <button class="edit-edit" data-id="${_escAttr(item.id)}">Editar</button>
      <button class="edit-del" data-id="${_escAttr(item.id)}">Remover</button></td></tr>`).join('')}</tbody></table>`;
  listEl.querySelectorAll('.edit-edit').forEach(b=>b.onclick=()=>_editForm(_editDados.find(d=>d.id===b.dataset.id)));
  listEl.querySelectorAll('.edit-del').forEach(b=>b.onclick=()=>_editRemover(b.dataset.id));
  traduzir(listEl);
}

function _campoHTML(f,val){
  const id='ef_'+f.k;
  if(f.t==='ts') return `<label class="edit-field"><span>${f.l}</span><input type="text" id="${id}" value="${_escAttr(_fmtData(val))}" disabled></label>`;
  if(f.t==='ro') return `<label class="edit-field"><span>${f.l}</span><input type="text" id="${id}" value="${_escAttr(val)}" disabled></label>`;
  if(f.t==='anexos'){
    const arr=(Array.isArray(val)?val:[]).filter(a=>a&&typeof a.url==='string');
    // só data:image/ (miniatura <img>, seguro) ou https:// (link) são aceitos;
    // qualquer outro esquema injetado direto no Firestore vira texto inerte.
    const ehImg=(u)=>/^data:image\//i.test(String(u||''));
    const ehHttp=(u)=>/^https:\/\//i.test(String(u||''));
    const itens=arr.length
      ? arr.map(a=>{ const u=String(a.url||''); const nome=_escHTML(a.nome||'imagem');
          if(ehImg(u)) return `<figure class="fb-anexo-thumb"><img src="${_escAttr(u)}" alt="${_escAttr(a.nome||'imagem')}" loading="lazy"><figcaption>${nome}</figcaption></figure>`;
          if(ehHttp(u)) return `<a href="${_escAttr(u)}" target="_blank" rel="noopener noreferrer" class="fb-anexo-link">🖼️ ${nome}</a>`;
          return `<span class="fb-anexo-link">🖼️ ${nome}</span>`; }).join('')
      : '<span class="fb-anexo-vazio">sem imagens</span>';
    return `<div class="edit-field edit-field-wide"><span>${f.l}</span><div class="fb-anexos-view">${itens}</div></div>`;
  }
  if(f.t==='select') return `<label class="edit-field"><span>${f.l}${f.req?' *':''}</span><select id="${id}"><option value="">·</option>${f.ops.map(o=>`<option value="${_escAttr(o[0])}"${o[0]===val?' selected':''}>${o[1]}</option>`).join('')}</select></label>`;
  if(f.t==='bool') return `<label class="edit-field edit-field-bool"><input type="checkbox" id="${id}"${val?' checked':''}><span>${f.l}</span></label>`;
  if(f.t==='textarea') return `<label class="edit-field edit-field-wide"><span>${f.l}${f.req?' *':''}</span><textarea id="${id}" rows="2">${_escHTML(val)}</textarea></label>`;
  if(f.t==='number') return `<label class="edit-field"><span>${f.l}${f.req?' *':''}</span><input type="number" id="${id}" value="${val!=null?_escAttr(val):''}"></label>`;
  const csv=(f.t==='csv'||f.t==='csvnum'); const vv=csv&&Array.isArray(val)?val.join(', '):val;
  return `<label class="edit-field"><span>${f.l}${f.req?' *':''}</span><input type="text" id="${id}" value="${vv!=null?_escAttr(vv):''}" placeholder="${_escAttr(f.ph||'')}"></label>`;
}

function _editForm(item){
  const cfg=EDIT_COLS[_editCol]; const novo=!item; item=item||{};
  const wrap=document.getElementById('editFormWrap'); if(!wrap) return;
  wrap.innerHTML=`<div class="edit-form">
    <h3>${novo?'Novo registro':'Editar registro'} · ${cfg.titulo}</h3>
    <div class="edit-form-grid">${cfg.campos.map(f=>_campoHTML(f,item[f.k])).join('')}</div>
    <div class="edit-form-actions">
      <button class="edit-cancel" id="efCancel">Cancelar</button>
      <button class="edit-save" id="efSave">Salvar</button>
      <span class="edit-form-msg" id="efMsg"></span>
    </div>
  </div>`;
  wrap.scrollIntoView({behavior:'smooth',block:'nearest'});
  document.getElementById('efCancel').onclick=()=>{ wrap.innerHTML=''; };
  document.getElementById('efSave').onclick=()=>_editSalvar(item,novo);
  traduzir(wrap);
}

async function _editSalvar(orig,novo){
  const cfg=EDIT_COLS[_editCol]; const msg=document.getElementById('efMsg');
  const dados={};
  for(const f of cfg.campos){
    if(f.t==='ts'||f.t==='ro'||f.t==='anexos') continue;
    const el=document.getElementById('ef_'+f.k); if(!el) continue;
    if(f.t==='bool') dados[f.k]=el.checked;
    else if(f.t==='number') dados[f.k]=el.value===''?null:Number(el.value);
    else if(f.t==='csv') dados[f.k]=el.value.split(',').map(s=>s.trim()).filter(Boolean);
    else if(f.t==='csvnum') dados[f.k]=el.value.split(',').map(s=>s.trim()).filter(s=>s!=='').map(Number).filter(n=>!isNaN(n));
    else dados[f.k]=el.value.trim();
  }
  const falta=cfg.campos.find(f=>{ if(!f.req) return false; const v=dados[f.k]; if(Array.isArray(v)) return v.length===0; return v==null||v===''; });
  if(falta){ if(msg){msg.textContent='Preencha: '+falta.l; msg.className='edit-form-msg erro';} return; }
  const id=novo?(gerarId(cfg.prefixo,dados[cfg.rotulo])+'_'+Math.random().toString(36).slice(2,7)):orig.id;
  const btn=document.getElementById('efSave'); if(btn) btn.disabled=true;
  if(msg){ msg.textContent='Salvando…'; msg.className='edit-form-msg'; }
  try{
    await salvarRegistro(_editCol,id,dados,USER_ATUAL);
    const w=document.getElementById('editFormWrap'); if(w) w.innerHTML='';
    await _editCarregarLista();
    _editRefreshGlobais();
    _editFlash('Registro salvo ✓');
  }catch(e){
    if(btn) btn.disabled=false;
    if(msg){ msg.textContent='Erro ao salvar: '+(e&&e.message||e); msg.className='edit-form-msg erro'; }
  }
}

async function _editRemover(id){
  if(!confirm('Remover este registro? (remoção lógica, pode ser restaurada no banco.)')) return;
  try{ await removerRegistro(_editCol,id,USER_ATUAL); await _editCarregarLista(); _editRefreshGlobais(); _editFlash('Registro removido ✓'); }
  catch(e){ _editFlash('Erro: '+(e&&e.message||e),true); }
}

function _editFlash(txt,erro){
  const s=document.getElementById('editStatus'); if(!s) return;
  s.textContent=txt; s.className='edit-status'+(erro?' erro':' ok');
  setTimeout(()=>{ if(s){s.textContent=''; s.className='edit-status';} },3500);
}

// atualiza os globais do dashboard após um save/remove, sem re-renderizar a view de edição (evita re-render reentrante)
async function _editRefreshGlobais(){ try{ const d=await carregarDados(); if(d) aplicarDados(d); }catch(_){} }

